begin;
select plan(26);
select is((select total_active from public.public_catalog_snapshot),(select count(*) from public.exercise_catalog where status='published' and is_active),'bootstrap is exact');
select ok((select generation=published_generation from private.public_catalog_refresh),'bootstrap acknowledged');
select is((select count(*) from cron.job where jobname='refresh-public-catalog-snapshot'),1::bigint,'one durable cron');
create temp table baseline as select total_active,revision,updated_at from public.public_catalog_snapshot;
insert into public.exercise_catalog(id,provider,provider_exercise_id,name,status)
values('98ca0000-0000-0000-0000-000000000001','evolutus_dataset','home-v2-snapshot','Snapshot draft','draft');
select is((select generation::text from private.public_catalog_refresh),(select revision from baseline),'draft insert does not enqueue');
update public.exercise_catalog set name='Edited draft' where id='98ca0000-0000-0000-0000-000000000001';
select is((select generation::text from private.public_catalog_refresh),(select revision from baseline),'draft edit does not enqueue');
update public.exercise_catalog set status='published',primary_muscle='peito',muscles=array['peito'],category='forca',instructions=array['Empurre'] where id='98ca0000-0000-0000-0000-000000000001';
select ok((select generation>published_generation from private.public_catalog_refresh),'publication durably queued');
select is((select total_active from public.public_catalog_snapshot),(select total_active from baseline),'no premature success before processing');
select private.refresh_public_catalog_snapshot();
select is((select total_active from public.public_catalog_snapshot),(select total_active+1 from baseline),'publication recalculates current state');
create temp table published_snapshot as select * from public.public_catalog_snapshot;
update public.exercise_catalog set pending_content='{"name":"Pending edit"}' where id='98ca0000-0000-0000-0000-000000000001';
select private.refresh_public_catalog_snapshot();
select is((select revision from public.public_catalog_snapshot),(select revision from published_snapshot),'published pending content causes no count refresh');
select is((select updated_at from public.public_catalog_snapshot),(select updated_at from published_snapshot),'no-op leaves original snapshot valid');
update public.exercise_catalog set status='withdrawn' where id='98ca0000-0000-0000-0000-000000000001';
select private.refresh_public_catalog_snapshot();
select is((select total_active from public.public_catalog_snapshot),(select total_active from baseline),'withdrawal decrements real total');
update public.exercise_catalog set status='published' where id='98ca0000-0000-0000-0000-000000000001';
select private.refresh_public_catalog_snapshot();
select is((select total_active from public.public_catalog_snapshot),(select total_active+1 from baseline),'republication restores real total');
select private.refresh_public_catalog_snapshot();
select private.refresh_public_catalog_snapshot();
select is((select generation::text from private.public_catalog_refresh),(select revision from public.public_catalog_snapshot),'duplicate/out-of-order wakeups cannot regress');
-- Simulate a publication failure: the acknowledgement must roll back too.
create function pg_temp.fail_snapshot() returns trigger language plpgsql as $$begin raise exception 'SIMULATED_STORAGE_FAILURE';end$$;
create trigger simulated_snapshot_failure before update on public.public_catalog_snapshot for each row execute function pg_temp.fail_snapshot();
update public.exercise_catalog set status='withdrawn' where id='98ca0000-0000-0000-0000-000000000001';
select throws_ok($$select private.refresh_public_catalog_snapshot()$$,'P0001','SIMULATED_STORAGE_FAILURE','processing failure is visible');
select ok((select generation>published_generation from private.public_catalog_refresh),'failure remains pending for automatic retry');
drop trigger simulated_snapshot_failure on public.public_catalog_snapshot;
select private.refresh_public_catalog_snapshot();
select is((select total_active from public.public_catalog_snapshot),(select total_active from baseline),'retry converges without event payload deltas');
select ok((select generation=published_generation from private.public_catalog_refresh),'retry acknowledges only the committed snapshot');
select is((select count(*)::int from pg_proc p where p.pronamespace='private'::regnamespace and p.proname in ('queue_public_catalog_refresh','refresh_public_catalog_snapshot') and p.proconfig @> array['search_path=pg_catalog, public, private, pg_temp']),2,'both definer paths explicitly place pg_temp last');
select ok(not has_function_privilege('anon','private.refresh_public_catalog_snapshot()','execute'),'anonymous cannot run processor');
select ok(not has_function_privilege('authenticated','private.refresh_public_catalog_snapshot()','execute'),'users cannot run processor');
select ok(not has_table_privilege('anon','public.public_catalog_snapshot','update'),'anonymous cannot edit snapshot');
select ok(not has_table_privilege('authenticated','public.public_catalog_snapshot','insert'),'users cannot create snapshot');
select ok(not has_table_privilege('anon','private.public_catalog_refresh','select'),'queue private');
set local role anon;
select is((select count(*) from public.public_catalog_snapshot),1::bigint,'anonymous can read only public singleton');
select throws_ok($$update public.public_catalog_snapshot set total_active=999$$,'42501','permission denied for table public_catalog_snapshot','anonymous write rejected');
reset role;
-- A rolled-back catalogue change must not leave a refresh event.
savepoint unpublished;
update public.exercise_catalog set status='published' where id='98ca0000-0000-0000-0000-000000000001';
rollback to unpublished;
select ok((select generation=published_generation from private.public_catalog_refresh),'rolled-back event disappears with source transaction');
select * from finish();
rollback;
